package org.usbworkbench;
import java.io.*;import java.nio.charset.*;import java.security.*;import java.util.*;
/** Standard raw console part files. The separate manifest is app metadata, never a part header. */
public final class ConsoleParts {
 public static final long MAX_BYTES=64L*1024*1024*1024;private static final byte[] MAGIC={'U','W','P','S','3','P','0','1'};
 public interface Sink{OutputStream create(String name)throws IOException;InputStream reopen(String name)throws IOException;void sync(String name)throws IOException;}
 public interface Part{long size()throws IOException;InputStream input()throws IOException;}
 public static final class Piece{public final long bytes;private final byte[] digest;Piece(long n,byte[] d){bytes=n;digest=d.clone();}}
 public static final class Manifest{
  public final String name,kind;public final long bytes,partSize;public final List<Piece> pieces;private final byte[] digest;
  private Manifest(String n,String k,long size,long partSize,List<Piece> p,byte[] hash)throws IOException{name=n;kind=k;bytes=size;this.partSize=partSize;pieces=Collections.unmodifiableList(new ArrayList<>(p));digest=hash.clone();validate(this);}
  public String partName(int index){return name+(kind.equals("iso")?".":".666")+(kind.equals("iso")?Integer.toString(index):String.format(Locale.ROOT,"%02d",index));}
  public String manifestName(){return name+".usbwb";}public String hash(){return hex(digest);}
  public byte[] encode()throws IOException{ByteArrayOutputStream buffer=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(buffer);out.write(MAGIC);out.writeByte(kind.equals("iso")?1:2);out.writeLong(bytes);out.writeLong(partSize);out.writeInt(pieces.size());byte[] text=name.getBytes(StandardCharsets.UTF_8);out.writeShort(text.length);out.write(text);for(Piece p:pieces){out.writeLong(p.bytes);out.write(p.digest);}out.write(digest);out.flush();byte[] body=buffer.toByteArray();out.write(sha().digest(body));out.flush();return buffer.toByteArray();}
 }
 private static MessageDigest sha(){try{return MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new AssertionError(e);}}
 private static String hex(byte[] b){StringBuilder out=new StringBuilder();for(byte x:b)out.append(String.format(Locale.ROOT,"%02x",x&255));return out.toString();}
 public static void name(String name,String kind)throws IOException{
  if(!kind.equals("iso")&&!kind.equals("666"))throw new IOException("CONSOLE_OPTIONS");if(name==null||name.isEmpty()||name.length()>120||name.equals(".")||name.equals("..")||name.endsWith(".")||name.endsWith(" ")||name.matches(".*[<>:\"/\\\\|?*].*")||name.matches("(?i)(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\\..*)?"))throw new IOException("CONSOLE_NAME");
  for(int i=0;i<name.length();i++){char c=name.charAt(i);if(c<32||c==127)throw new IOException("CONSOLE_NAME");if(Character.isHighSurrogate(c)){if(++i>=name.length()||!Character.isLowSurrogate(name.charAt(i)))throw new IOException("CONSOLE_NAME");}else if(Character.isLowSurrogate(c))throw new IOException("CONSOLE_NAME");}if(name.getBytes(StandardCharsets.UTF_8).length>220)throw new IOException("CONSOLE_NAME");if(kind.equals("iso")&&!name.toLowerCase(Locale.ROOT).endsWith(".iso"))throw new IOException("CONSOLE_NAME");
 }
 private static void validate(Manifest m)throws IOException{name(m.name,m.kind);if(m.bytes<1||m.bytes>MAX_BYTES||m.partSize<2048||m.partSize%2048!=0||m.partSize>0xffffffffL||m.pieces.isEmpty()||m.pieces.size()>64||m.pieces.size()!=(m.bytes+m.partSize-1)/m.partSize||m.digest.length!=32||m.kind.equals("iso")&&m.bytes%2048!=0)throw new IOException("CONSOLE_MANIFEST");long left=m.bytes;for(Piece p:m.pieces){long want=Math.min(left,m.partSize);if(p.bytes!=want||p.digest.length!=32)throw new IOException("CONSOLE_MANIFEST");left-=want;}}
 public static Manifest read(InputStream source)throws IOException{
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[1024];int n;while((n=source.read(buffer))!=-1){if(n<=0||bytes.size()>8192-n)throw new IOException("CONSOLE_MANIFEST");bytes.write(buffer,0,n);}byte[] all=bytes.toByteArray();if(all.length<100)throw new IOException("CONSOLE_MANIFEST");byte[] body=Arrays.copyOf(all,all.length-32);if(!MessageDigest.isEqual(sha().digest(body),Arrays.copyOfRange(all,all.length-32,all.length)))throw new IOException("CONSOLE_MANIFEST");
  try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(body))){byte[] magic=new byte[8];in.readFully(magic);if(!Arrays.equals(magic,MAGIC))throw new IOException("CONSOLE_MANIFEST");int type=in.readUnsignedByte();if(type!=1&&type!=2)throw new IOException("CONSOLE_MANIFEST");long size=in.readLong(),partSize=in.readLong();int count=in.readInt(),length=in.readUnsignedShort();if(count<1||count>64||length<1||length>1024)throw new IOException("CONSOLE_MANIFEST");byte[] text=new byte[length];in.readFully(text);String name;try{name=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(text)).toString();}catch(CharacterCodingException e){throw new IOException("CONSOLE_MANIFEST",e);}List<Piece> pieces=new ArrayList<>();for(int i=0;i<count;i++){long part=in.readLong();byte[] hash=new byte[32];in.readFully(hash);pieces.add(new Piece(part,hash));}byte[] hash=new byte[32];in.readFully(hash);if(in.read()!=-1)throw new IOException("CONSOLE_MANIFEST");return new Manifest(name,type==1?"iso":"666",size,partSize,pieces,hash);
  }catch(EOFException e){throw new IOException("CONSOLE_MANIFEST",e);}
 }
 public static Manifest split(OpticalImage.Source source,String name,String kind,long partSize,Sink sink,DiskTools.Progress p)throws IOException{
  name(name,kind);long size=source.size();if(size<1||size>MAX_BYTES||partSize<2048||partSize%2048!=0||partSize>0xffffffffL||(size+partSize-1)/partSize>64||kind.equals("iso")&&size%2048!=0)throw new IOException("CONSOLE_OPTIONS");byte[] b=new byte[65536];MessageDigest all=sha();List<Piece> pieces=new ArrayList<>();long done=0;
  for(int index=0;done<size;index++){long count=Math.min(partSize,size-done);String path=name+(kind.equals("iso")?".":".666")+(kind.equals("iso")?Integer.toString(index):String.format(Locale.ROOT,"%02d",index));MessageDigest hash=sha();try(OutputStream out=sink.create(path)){for(long at=0;at<count;){p.update(done*2+at,size*2);int n=(int)Math.min(b.length,count-at);source.read(done+at,b,0,n);out.write(b,0,n);hash.update(b,0,n);all.update(b,0,n);at+=n;}out.flush();}sink.sync(path);byte[] expected=hash.digest();try(InputStream in=sink.reopen(path)){if(!MessageDigest.isEqual(expected,hash(in,count,p,done*2+count,size*2)))throw new IOException("VERIFY_FAILED");}pieces.add(new Piece(count,expected));done+=count;}
  if(source.size()!=size)throw new IOException("SOURCE_CHANGED");Manifest m=new Manifest(name,kind,size,partSize,pieces,all.digest());byte[] metadata=m.encode();try(OutputStream out=sink.create(m.manifestName())){out.write(metadata);out.flush();}sink.sync(m.manifestName());try(InputStream in=sink.reopen(m.manifestName())){Manifest saved=read(in);if(!MessageDigest.isEqual(saved.encode(),metadata))throw new IOException("VERIFY_FAILED");}p.update(size*2,size*2);return m;
 }
 private static byte[] hash(InputStream in,long size,DiskTools.Progress p,long base,long total)throws IOException{MessageDigest hash=sha();byte[] b=new byte[65536];long done=0;while(done<size){p.update(base+done,total);int n=in.read(b,0,(int)Math.min(b.length,size-done));if(n<=0)throw new IOException("CONSOLE_PART_SIZE");hash.update(b,0,n);done+=n;}if(in.read()!=-1)throw new IOException("CONSOLE_PART_SIZE");return hash.digest();}
 public static void join(Manifest m,Map<String,Part> parts,OutputStream output,DiskTools.Progress p)throws IOException{
  validate(m);if(parts.size()!=m.pieces.size())throw new IOException("CONSOLE_PARTS");for(int i=0;i<m.pieces.size();i++){Part part=parts.get(m.partName(i));if(part==null||part.size()!=m.pieces.get(i).bytes)throw new IOException("CONSOLE_PARTS");}
  MessageDigest all=sha();byte[] b=new byte[65536];long done=0;
  for(int i=0;i<m.pieces.size();i++){Piece piece=m.pieces.get(i);MessageDigest hash=sha();try(InputStream in=parts.get(m.partName(i)).input()){long at=0;while(at<piece.bytes){p.update(done+at,m.bytes);int n=in.read(b,0,(int)Math.min(b.length,piece.bytes-at));if(n<=0)throw new IOException("CONSOLE_PART_SIZE");if(output!=null)output.write(b,0,n);hash.update(b,0,n);all.update(b,0,n);at+=n;}if(in.read()!=-1)throw new IOException("CONSOLE_PART_SIZE");}if(!MessageDigest.isEqual(hash.digest(),piece.digest))throw new IOException("CONSOLE_PART_CORRUPT");done+=piece.bytes;}
  if(!MessageDigest.isEqual(all.digest(),m.digest))throw new IOException("CONSOLE_PART_CORRUPT");if(output!=null)output.flush();p.update(m.bytes,m.bytes);
 }
 public static void verifyJoined(Manifest m,InputStream saved,DiskTools.Progress p)throws IOException{if(!MessageDigest.isEqual(hash(saved,m.bytes,p,0,m.bytes),m.digest))throw new IOException("VERIFY_FAILED");}
}
